// Viṣṇu Sahasranāma — concepts 301–400 (English, own paraphrases).
// Same conventions as vs-concepts-001-100.ts.
export const vsConcepts301400: any[] = [
  { id: "vs-nama-301", title: "Yugāvartaḥ", category: "Fire-Sun", summary: "Who turns the yugas round again and again. After making the yugas' dawns (previous name), He revolves them: recurrence as rhythm, history circling because He circles it — creation, decay and renewal wheeling like seasons on a cosmic scale. The two names together hold beginning and repetition: He both opens epochs and returns them, so no age is final and no ending is ultimate. Trust one return today: a cycle coming round is His turning, not your failure. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-302", title: "Naikamāyaḥ", category: "Fire-Sun", summary: "Wielder of manifold illusion. Naika-māya joins many (naika) with measure-making power (māyā): veils uncounted, one Veiler — multiplicity managed from unity, enchantment administered, never suffered. Māyā here is His instrument, not His condition: He wields manifold display the way a magician wields apparatus, untouched by the wonder He stages. The verse stations illusion between age-turning and devouring, so time's marvels read as staged, not ultimate. See one veil through today. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-303", title: "Mahāśanaḥ", category: "Fire-Sun", summary: "The great devourer swallowing all. Mahā-aśana is appetite cosmic: time eats worlds, and He is time's hunger — ages consumed, empires digested, the endless appetite (amitāśana, name 372) previewed here. Devouring reads as homecoming rather than horror: what He eats returns into Him, the way waves return into ocean. He starts ages, turns them, eats them — the verse's triple mastery of time. Feed one ending to Him today instead of merely mourning it. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-304", title: "Adṛśyaḥ", category: "Fire-Sun", summary: "The unseen. Adṛśya names invisibility as excess of presence, not absence: too near for sight, as eyes see all but themselves, too pervasive for pointing. The verse pairs Him with manifest form (next name) so that hiddenness never reads as distance — He is unseen the way the seer is unseen, present at every seeing as its ground. What cannot be objectified need not be doubted. Honour one unseen today: the ground of your own seeing. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-305", title: "Vyaktarūpaḥ", category: "Fire-Sun", summary: "Of manifest form — this edition's reading against avyakta elsewhere, recorded not smoothed over. Vyakta-rūpa is display gracious: the Unseen consenting to be seen, hiddenness yielding to love, form assumed for yogīs' vision and devotees' embrace. With adṛśya (previous name) this states the whole theology of incarnation: unseen in essence, manifest in grace — hidden in display, as the verse's commentary has it. Receive one manifestation gratefully today, a form through which the Formless looked at you. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-306", title: "Sahasrajit", category: "Fire-Sun", summary: "Vanquisher of thousands. Sahasrajit masters multitudes: armies routed, obstacles felled, births outlasted — thousands bow because number itself bows before the Numberless. Conquest here is liberation's arithmetic: every thousand conquered is a thousand bonds broken, and the devotee's thousand-fold habits (a fear repeated a thousand mornings) fall under the same victory. The verse scales conquest from thousands to the endless (next name). Vanquish one thousand-fold habit today — the one that claims numbers as excuse. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-307", title: "Anantajit", category: "Fire-Sun", summary: "Ever-victorious without end. Anantajit triumphs timelessly: no final battle because victory is nature, not event — He does not win, He is winning, the way light does not defeat darkness in campaigns but by being. After thousands (previous name) comes the endless: quantity conquered, then conquest itself transcended into eternity. The verse closes time's arc here — started, turned, devoured, unseen, manifest, conquering — all within one breath. Triumph once today timelessly: act from victory, not toward it. (Stotra verse 33.)", relatedVerseIds: ["vs-033"] },
  { id: "vs-nama-308", title: "Iṣṭaḥ", category: "Fire-Sun", summary: "The worshipped, beloved by all. Iṣṭa is devotion's darling: sought in sacrifice, loved in heart, the one address to which all offerings are posted and from which all fulfilment returns. Worship ripens into belovedness across this verse (śiṣṭeṣṭa follows): ritual becomes affection, the adored becomes the dear. To be worshipped by all while belonging to each — universality without dilution — is the paradox of this name. Love once today universally: direct one affection past its usual boundaries. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-309", title: "Aviśiṣṭaḥ", category: "Fire-Sun", summary: "The undifferentiated, noblest and most sacred. Aviśiṣṭa dissolves distinction upward: nobility past categories, sacredness past sects — not featureless blankness but fullness refusing pigeonholes, excellence that no comparison contains (atula, name 355, echoes this). After the worshipped (previous name) comes the worshipped-beyond-partition: all love arrives at One who outranks every division love might honour. Honour one undifferentiated nobility today: excellence wearing no uniform. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-310", title: "Śiṣṭeṣṭaḥ", category: "Fire-Sun", summary: "Dear to the learned and disciplined. Śiṣṭeṣṭa returns worship's affection: the studied is sweet to studiers, the mastered beloved of masters — wisdom loving Him back because He first loved wisdom into them. Iṣṭa (worshipped by all) narrows to the disciplined few, then widens again: the verse teaches that ritual becomes affection fastest in trained hearts. Study endears; discipline sweetens. Endear one study today: pursue a discipline until it turns into affection. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-311", title: "Śikhaṇḍī", category: "Fire-Sun", summary: "Peacock-crested. Śikhaṇḍin crowns cosmic kingship with forest feather: playfulness enthroned, wild beauty set above sovereignty — the Kṛṣṇa-crest that turns terror beautiful, as the verse's commentary notes, keeping the universe-arms (name 316) from reading as mere force. Adornment is doctrine: the Lord beautifies power so that power invites rather than intimidates. Among anger-names (next), the crest promises that wrath serves beauty. Wear one wild adornment today: a gladness set visibly above your duties. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-312", title: "Nahuṣaḥ", category: "Fire-Sun", summary: "Who binds souls by gracious illusion. Nahuṣa ties that teach: bonds as lessons, knots as instructors — the soul tethered by enchanting circumstance until it learns what tethering means. The tradition hears here both the binding power of māyā (naika-māyā, name 302, now personalized as Binder) and the humbled king Nahuṣa's tale, pride bound into serpent-hood until humility unbound it. Bondage pedagogic, never pointless. Learn one knot's lesson today instead of merely resenting the rope. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-313", title: "Vṛṣaḥ", category: "Fire-Sun", summary: "Who fulfils desires like rain. Vṛṣa showers bestowal: blessings precipitated, wishes watered — the dharma-bull of the vṛṣa-cluster (names 256–260) returning as rain-giver, righteousness now raining fulfilment. Desire answered by downpour rather than ration: heaven's water on parched asking. After binding (previous name) comes raining — knots, then monsoon. Rain one fulfilment today: grant a right asking generously, shower-fashion. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-314", title: "Krodhahā", category: "Fire-Sun", summary: "Destroyer of anger in seekers. Krodhahan withers wrath: fury dried at root, rage unwatered until it crisps and crumbles — grace's drought applied precisely where anger drinks. The verse handles anger three ways across these names: destroyed here, administered next, mastered throughout. Destruction of anger is protection of the angry: wrath harms its host first. Wither one wrath today: refuse its water — rehearsal, grievance, heat — and watch it crisp. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-315", title: "Krodhakṛtkartā", category: "Fire-Sun", summary: "Maker-and-doer concerning anger — one name, krodhakṛt joined to kartā. Wrath has its maker, measure and master: anger generated for justice, authored against baseness, administered under licence — holy anger forged as instrument, never suffered as possession. He destroys anger (previous name) yet authors it: the contradiction resolves in mastery — fury exists, but only on His leash. Forge one holy anger today if needed: against a baseness, measured, mastered, and sheathed after use. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-316", title: "Viśvabāhuḥ", category: "Fire-Sun", summary: "Whose arms are everywhere in the universe. Viśvabāhu extends help to every address: assistance omnipresent, rescue within reach from all sides — no quarter beyond arm's length, no cry outside embrace. Arms that were fair (subhuja, name 265) and hard to hold (durdhar) are now everywhere: beauty, mystery, ubiquity in sequence. The peacock crest (name 311) keeps these arms beautiful. Lend one everywhere-hand today: reach somewhere beyond your usual radius. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-317", title: "Mahīdharaḥ", category: "Fire-Sun", summary: "Supporter of the earth — the verse's closing bearer, dharaṇīdhara (name 235) restated. Ground re-grounded: support repeated lest worlds forget their Bearer amid worship, crest, rain and wrath. Repetition is itself support — the hymn holds up the world by re-saying its Holder. Universe-arms (previous name) narrow to earth-arms: omnipresence focusing on the ground beneath your feet. Thank the Bearer again today, specifically for ground. (Stotra verse 34.)", relatedVerseIds: ["vs-034"] },
  { id: "vs-nama-318", title: "Acyutaḥ", category: "Fire-Sun", summary: "The unfailing, who never slips (named again). Acyuta re-confirms constancy for slipping hearts: the Unslipping restated exactly where the verse stoops to humility — infallibility expressing as younger brotherhood (next names). What never changes changes costume: Vāmana's smallness worn by the never-diminished. Repetition steadies: each recurrence a handrail on a different staircase. Restate one constancy today: an old trust, re-spoken to a new fear. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-319", title: "Prathitaḥ", category: "Fire-Sun", summary: "Famed, pervading all in renown. Prathita spreads fame coextensive with reality: known where He is, which is everywhere — renown as the sound of omnipresence, glory as pervasion made audible. Viśrutātman (name 207) returns in fuller voice: Veda-fame grown into world-fame. Fame founded on being (as established there) now floods all beings. Spread one good fame today: speak someone's true excellence where it will do good. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-320", title: "Prāṇaḥ", category: "Fire-Sun", summary: "Soul-breath in all creatures (named again). Vitality re-breathed: life restated as His exhalation, every inhalation a loan renewed, existence re-issued with each breath. The early prāṇa (name 66) returns after unfailing fame — breath backed by infallibility, respiration guaranteed by the Unslipping. To breathe is to be held; to live, to be lent to. Breathe one restatement today: an inhalation received as re-issue. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-321", title: "Prāṇadaḥ", category: "Fire-Sun", summary: "Giver of breath and strength (named again). Vigour re-given: energy reissued to the weary, the grant underlying all grants renewed with every dawn. Prāṇa (previous name) as being, prāṇada as giving — He is the breath and its Giver, the loan and the Lender. His sleeplessness is our oxygen (verse theme): vigilance respirated into creatures. Reissue one vigour today: lend breath to something tired — an endeavour, a person, yourself. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-322", title: "Vāsavānujaḥ", category: "Fire-Sun", summary: "Younger brother of Indra — Vāmana beside the thunder-king. Seniority surrendered: greatness playing junior, omnipotence as kid brother, infallibility (acyuta, name 318) expressing as humility. The dwarf-avatāra's courtesy — begging three steps from Bali while upholding Indra's heaven — makes smallness the signature of supremacy. Might as humility is the verse's heart. Play junior once gladly today: yield precedence without yielding worth. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-323", title: "Apāṃnidhiḥ", category: "Fire-Sun", summary: "Ocean, treasure of waters. Apāṃnidhi hoards depth: mysteries stored fathom-deep, pearls kept under pressure — treasure hidden in waters, as the verse's key point has it. Nidhi the imperishable (name 30) returns liquefied: inexhaustibility now oceanic, giving without depleting because depths are unplumbed. The small brother (previous name) contains oceans. Dive one depth today: a mystery — scripture, sorrow, another heart — entered rather than skimmed. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-324", title: "Adhiṣṭhānam", category: "Fire-Sun", summary: "Substratum of the universe. Adhiṣṭhāna underlies absolutely: all standings stand on this Standing, every support supported, foundations founded. The ocean (previous name) has a floor, and the floor is Him; establishment (next name) stands on this Standing. Philosophy's ground-term worn as devotion's name: the Absolute as carpet beneath existence. Stand on it once today: place one weight — a worry, a plan — directly on the Underlying. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-325", title: "Apramattaḥ", category: "Fire-Sun", summary: "Ever-vigilant, never erring in judgment. Apramatta attends flawlessly: no oversight, no slip, no nodding — the unwinking Lord (animiṣa, name 215) now applied to judgment, vigilance ripened into inerrancy. Breath given (names 320–321) is breath watched: His sleeplessness guards every loan He issues. Human vigilance borrows His: attention apprenticed to Attention. Attend once today flawlessly: a single duty done with whole, unnodding care. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-326", title: "Pratiṣṭhitaḥ", category: "Fire-Sun", summary: "Firmly established, self-founded. Pratiṣṭhita founds on Self: establishment ultimate, needing no foundation because it is foundation — the substratum (previous name) standing on itself, ground grounding itself. The verse closes here: ocean, substratum, vigilance, establishment — depth, ground, watch, rest. Rest on the foundation instead of building on sand (verse counsel). Found one act today on Self: done for the Self, resting in the Self. (Stotra verse 35.)", relatedVerseIds: ["vs-035"] },
  { id: "vs-nama-327", title: "Skandaḥ", category: "Lotus-Resolve", summary: "The commander, whose glory shines as Subrahmaṇya. Skanda marshals divine strategy: generalship sacred, assault ordered, the war against darkness conducted rather than merely wished. Command opens the new verse-arc (lotus, measure, resolve): authority that acts, after establishment that rests. The same root yields bearer-of-command (next name): command given, command carried — hierarchy entire. Marshal one endeavour today: give a scattered effort rank, file, and objective. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-328", title: "Skandadharaḥ", category: "Lotus-Resolve", summary: "Bearer of the commander's path, upholder of the way. Skandadhara seconds authority: power propped by principle, command carried by dharma's shoulders — the general's orders borne by the order that outranks generals. Command (previous name) paired with carriage: authority completed by responsibility, as the verse's commentary notes — pulling its weight. Prop one authority today: uphold a right command by carrying your share of its weight. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-329", title: "Dhuryaḥ", category: "Lotus-Resolve", summary: "Bearer of the yoke, carrying the pole's weight. Dhurya shoulders centrality: the cart-pole's load resting on this shoulder, the world's draught-work accepted — command (names 327–328) descending into harness. Authority proves itself in yoke-bearing: rank demonstrated by weight pulled, not tribute gathered. Pull one yoke cheerfully today as His (verse counsel): a duty's weight, shouldered without sulk. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-330", title: "Varadaḥ", category: "Lotus-Resolve", summary: "Giver of boons. Varada warrants wishes: asks answered, prayers pensioned — boons given, never sold, grace doing retail what providence does wholesale. After yoke-bearing (previous name) comes gift-giving: the shoulder that pulls also pours. Asking presumes a Giver; the Giver presumes asked-ness — prayer completes the circuit. Ask once today worthily: a right asking, plainly put, openly awaited. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-331", title: "Vāyuvāhanaḥ", category: "Lotus-Resolve", summary: "Controller of the winds, borne upon the wind. Vāyuvāhana administers airs: breezes bossed, storms supervised — motion's god (samīraṇa, anila) now openly ruled, winds ridden rather than merely released. Breath, storm, and spirit move under orders. Inner weather answers the same Controller: agitations are airs, and airs have a Master. Supervise one inner storm today: name the wind, invoke its Rider. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-332", title: "Vāsudevaḥ", category: "Lotus-Resolve", summary: "Vāsudeva — indweller of all, and son of Vasudeva. The name holds both readings at once: vasu-deva, the God who dwells (in all beings as wealth and light), and Vāsudeva, Kṛṣṇa the cowherd's son — immanence incarnate, within everything and born as someone. Indwelling tenderness with fortress-breaking force (verse theme, with purandara): the within-born breaks citadels. Greet the within-born today: the Indweller in one unlikely dwelling. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-333", title: "Bṛhadbhānuḥ", category: "Lotus-Resolve", summary: "Vastly radiant, whose rays spread everywhere. Bṛhadbhānu broadcasts radiance: light beamed boundless, day delivered to every address — the Indweller (previous name) shining outward, interior glory exteriorized. Vastness and radiance wed: not a point of light but an expanse of it, sunrise without horizon. Beam once today boundlessly: a gladness radiated past its usual circle. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-334", title: "Ādidevaḥ", category: "Lotus-Resolve", summary: "First god, primary source of everything. Ādideva personalizes primality: before every before, Someone — origination with a face, priority with a heart. Firstness here is not mere seniority but sourcery: all gods, worlds, and dawns derive, none precede. After vast radiance (previous name) comes first light: broadcast glory traced to its Prime. Honour the Primal Someone today: begin one thing by acknowledging the Beginner. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-335", title: "Purandaraḥ", category: "Lotus-Resolve", summary: "Breaker of citadels. Purandara storms strongholds: pride's walls breached, hostile fortresses felled — Indra's old title (sacker of the ninety-nine) reclaimed for the First God. The verse closes tenderness with force: Vāsudeva the indweller breaks citadels, love carrying siege-engines. Not all walls deserve standing; some enclosures imprison. Breach one pride-wall today — preferably your own, gently. (Stotra verse 36.)", relatedVerseIds: ["vs-036"] },
  { id: "vs-nama-336", title: "Aśokaḥ", category: "Lotus-Resolve", summary: "Sorrowless. Aśoka negates grief personally: sadness cannot approach, sorrow finds no seat — the Lord as grief's impossibility, and by remembrance its cure. The rescue-verse opens here (ferryman, star follow): grief removed before passage given, sorrowlessness as embarkation. His sorrowlessness is not distance from suffering but its solvent. Sit once today sorrowlessly: a grief held up to His grieflessness until it thins. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-337", title: "Tāraṇaḥ", category: "Lotus-Resolve", summary: "Ferryman helping cross becoming. Tāraṇa pilots passage: samsāra ferried, fares forgiven — the crossing operated by One who asks no coin but trust. Sorrowlessness (previous name) becomes service: His own freedom from grief ferries the grief-bound. Rescue in triplicate (verse theme: ferryman, star, hero) begins with the boat. Ferry once today forgiven: cross one water — a task, a grief — on His passage, fare remitted. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-338", title: "Tāraḥ", category: "Lotus-Resolve", summary: "The deliverer, star guiding night boats. Tāra doubles as star and saviour: rescue radical, drowning existence dived for, the sunk raised — direction shown while passage given (with tāraṇa, previous name). The star does not row; it guides: deliverance by illumination alongside deliverance by carriage. Steer by the star instead of staring at the waves (verse counsel). Rise once today rescued: lift eyes from waves to star. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-339", title: "Śūraḥ", category: "Lotus-Resolve", summary: "The valiant. Śūra is courage essential: bravery as being, not behaviour — valour's substance rather than its display. Rescue's triplicate completes with the hero: boat (tāraṇa), star (tāra), sword (śūra) — passage, direction, defence. Valour here guards the crossing: ferrymen need arms where waters are pirate-haunted. Be brave essentially once today: a courage that is, before it does. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-340", title: "Śauriḥ", category: "Lotus-Resolve", summary: "Born in Śūra's line — Vasudeva's son, Kṛṣṇa of the heroic house. Śauri wears lineage luminously: nobility inherited and surpassed, the hero's son out-heroing the sire. Valour (previous name) now has a genealogy: courage descends, houses hold it, blood remembers it — yet He exceeds every house He honours. Inherit one nobility today: a forebear's best quality, consciously received and deliberately exceeded. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-341", title: "Janeśvaraḥ", category: "Lotus-Resolve", summary: "Lord of the people. Janeśvara heads multitudes mercifully: crowds crowned rather than herded, populace ruled as persons, not mass. The hero's son (previous name) turns people's lord: lineage opening into populace, house into nation. Leadership proved by the led flourishing — the governed glad. Crown one crowd kindly today: serve a group — family, team, queue — as its lord-servant. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-342", title: "Anukūlaḥ", category: "Lotus-Resolve", summary: "Well-wisher of everyone, the favourable. Anukūla banks downstream with the swimmer: goodwill broadcast, benevolence beamed — the current itself befriending the boat. The people's Lord (previous name) favouring each person: populace ruled, persons befriended. Favour here is not favouritism but climate: all shores get the same river's help. Beam once today benevolently: favour someone who cannot repay. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-343", title: "Śatāvartaḥ", category: "Lotus-Resolve", summary: "Of infinite turns, hundred-turned. Śatāvarta has met every plight before: aspects uncounted, approaches endless — no strait surprises the hundred-turned Pilot, no distress is unprecedented to Him. Versatility vast is experience perfected: turns accumulated into mastery. The rescue-verse's assurance rests here: novelty of suffering meets antiquity of salvation. Approach once today variously: a stale problem, tried by a new turn of His. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-344", title: "Padmī", category: "Lotus-Resolve", summary: "Lotus-holder. Padman bears purity handheld: the unstained carried openly, innocence displayed, not hidden — conch, discus, mace, and lotus among His emblems, the lotus His gentlest weapon. Power holding purity: the hand that breaks citadels (name 335) holds a flower. Rescue's emblem closes here: passage given under sign of purity. Display one innocence today: an unstained thing — motive, memory, delight — carried openly. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-345", title: "Padmanibhekṣaṇaḥ", category: "Lotus-Resolve", summary: "Whose eyes are like lotus petals. Padmanibhekṣaṇa sees softly: vision floral, regard blooming — lotus-eyes (puṇḍarīkākṣa, aravindākṣa) now petal-soft, seeing without staining, knowing without searing. The rescue-verse closes on gaze: ferryman, star, hero, lord, friend — all arriving as look. To be seen thus is to be ferried. Regard once today bloomingly: look at someone the way petals open — softly, fully. (Stotra verse 37.)", relatedVerseIds: ["vs-037"] },
  { id: "vs-nama-346", title: "Padmanābhaḥ", category: "Lotus-Resolve", summary: "Lotus-navelled (named again). Creation's stalk restated: the umbilical bloom re-blooming in telling — Brahmā blossoming outward on the navel-lotus, worlds nursed from His centre. The early padmanābha (name 48) returns amid three lotuses (navel, eye, womb): cosmology re-bloomed after rescue, origin re-sung after deliverance. Re-bloom once today: revisit an origin — a birth, a beginning — and see it flowering still. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-347", title: "Aravindākṣaḥ", category: "Lotus-Resolve", summary: "Lotus-eyed like day-blooms. Aravindākṣa opens vision with dawn: eyes blooming as day-lotuses bloom, seeing with sunrise — compassion diurnal, regard renewed each morning. Among three lotuses (verse theme) this is the eye: creation (navel) watched by compassion (eye), gestated by tenderness (womb). Dawn-see once today: look at the day's first thing as though petals, and yours, were opening. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-348", title: "Padmagarbhaḥ", category: "Lotus-Resolve", summary: "Lotus-wombed, meditated in the heart's lotus. Padmagarbha interiors blooming: the heart's bud holding Him — gestation within, the cosmic lotus (previous names) miniaturized into the chest. Womb after navel and eye completes the body-bloom: origin, vision, interiority — all floral. Tend your body as His lotus-pond (verse counsel): the pond's stillness is meditation's. Bud once today inwardly: a quiet minute, heart-pond still. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-349", title: "Śarīrabhṛt", category: "Lotus-Resolve", summary: "Nourisher and bearer of bodies — one name in this edition's combined reading (with śarīrabhūtabhṛt variants elsewhere, recorded in provenance). Embodiment fed: every frame fuelled, all flesh sustained — bodies borne from within, not merely carried from beneath. The lotus-body (previous names) needs tending; this name is the tending. Bodies are His lotus-ponds, each requiring upkeep. Sustain one frame kindly today: your own or another's — food, rest, care. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-350", title: "Maharddhiḥ", category: "Lotus-Resolve", summary: "Lord of great prosperity. Maharddhi owns opulence: riches ruled, wealth wielded wisely — prosperity governed, not merely possessed. Growth with age (verse theme): ripening, never novelty — fortune seasoned, affluence matured. The lotus-body's bloom includes abundance: ponds flower, and flowering is wealth. Wield one wealth wisely today: a resource — coin, hour, skill — governed toward ripening. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-351", title: "Ṛddhaḥ", category: "Lotus-Resolve", summary: "Expanded as the universe itself. Ṛddha grows cosmic: enlargement to all-size, increase to infinity — prosperity (previous name) expanded into identity with the All. The ever-full (name 278) returns grown: fullness now universe-shaped. Growth is being here, not acquisition: to expand is to be, universally. Increase once today infinitely-minded: a small growth — patience, generosity — done as though universe-sized. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-352", title: "Vṛddhātmā", category: "Lotus-Resolve", summary: "The ancient Self. Vṛddhātman hallows age: seniority sacred, oldness venerable — antiquity as authority, the Ancient of ancients (jyeṣṭha, name 67, echoes). Prosperity as ripening (verse theme) needs this name: growth crowned by age, novelty humbled before seniority. Newness dazzles; antiquity anchors (as zones 1–2 established). Honour one oldness today: an elder, an old thing, an old truth — saluted, not shelved. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-353", title: "Mahākṣaḥ", category: "Lotus-Resolve", summary: "Great-eyed. Mahākṣa spans vision vast: sight reaching, regard gathering — the lotus-eyes (names 345, 347) widened to greatness, petals grown panoramic. Greatness of eye is greatness of care: what is seen widely is held widely. The Garuḍa-banner (next name) flies under these eyes: conquest watched over by compassion. Gaze once today vastly: take in a whole — a room, a street, a person's day — with gathering care. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-354", title: "Garuḍadhvajaḥ", category: "Lotus-Resolve", summary: "Whose banner bears Garuḍa. Garuḍadhvaja flags victory with wings: triumph flown, the Veda's wings (Garuḍa as Veda-embodied) carried into battle — scripture militant, soaring. The lotus-verse closes on war-banner: bloom guarded by pinions, pond patrolled by eagle. Tenderness needs talons where serpents (nāgas, Garuḍa's foes) threaten. Fly one triumph today: a victory — however small — flown openly, wings spread. (Stotra verse 38.)", relatedVerseIds: ["vs-038"] },
  { id: "vs-nama-355", title: "Atulaḥ", category: "Lotus-Resolve", summary: "Incomparable. Atula cancels comparison: scales snap, parallels perish — excellence past measure because measure presumes seconds, and there is none. Yet precisely marked (next verse-theme: beyond compare, within recognition): every auspicious mark present, no scale that holds Him. Incomparability is not vagueness but superabundance — too much, not too little, defeats compare. Cancel one comparison today: meet someone — yourself included — without ranking. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-356", title: "Śarabhaḥ", category: "Lotus-Resolve", summary: "Śarabha — the fierce eight-legged form that subdued Narasiṃha's excess, in this tradition His own awe. Fierceness redemptive: terror taming terror, awe awing evil — ferocity turned surgeon, operating on ferocity. After incomparability comes holy terror: beyond compare includes beyond comfort. Terror serves occasion-wisdom (verse theme with samayajña): fright timed and aimed. Awe one evil away today: let a dread of wrong do its surgical work. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-357", title: "Bhīmaḥ", category: "Lotus-Resolve", summary: "Terrible and awe-inspiring. Bhīma hallows dread: fear that purifies, terror that teaches — awe as pedagogy, fright as tutor. Śarabha (previous name) particularizes; bhīma universalizes: terribleness as standing attribute, dread available wherever evil swells. Holy terror guards holiness: what cannot frighten evil cannot shelter good. Learn one awe today: a fear — of consequence, of His gaze — kept as teacher, not trauma. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-358", title: "Samayajñaḥ", category: "Lotus-Resolve", summary: "Knower of fit occasions — and, in the twin reading, worshipped with equal vision. Samayajña times wisely: seasons sensed, moments mastered — terror (previous names) timed and aimed, never loose. Occasion-wisdom governs force: the terrible knows when, and knowing when is half of knowing how. The alternate sense crowns it: equal-eyed worship, sameness of vision — timing perfected into equanimity. Sense one season today: act now, or refrain now, in season. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-359", title: "Havirhariḥ", category: "Lotus-Resolve", summary: "Receiver of all oblations. Havirhari gathers gifts: offerings accepted, givings granted audience — every oblation, Vedic or vernacular, arriving at one altar. The oblation (havis) and its remover/receiver (hari): He takes what is given and takes away what binds the giver — reception as redemption. Terror and timing (previous names) open into welcome: awe's altar receives. Give once today acceptedly: an offering — effort, thanks, apology — laid where it will be received. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-360", title: "Sarvalakṣaṇalakṣaṇyaḥ", category: "Lotus-Resolve", summary: "Marked by every auspicious mark, known through all signs of inquiry — one long name, the hymn's longest. Evidence entire: every proof pointing, all signs signing — the Incomparable (name 355) fully recognizable, beyond compare yet within recognition (verse theme). Lakṣaṇa doubles as mark and definition: He bears all marks and satisfies all definitions, excess that includes precision. Follow one sign today: a mark of His — beauty, order, mercy — traced to its Bearer. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-361", title: "Lakṣmīvān", category: "Lotus-Resolve", summary: "Consort of Lakṣmī. Lakṣmīvān weds fortune: prosperity married to providence, wealth to wisdom — Śrīmān (names 22, 220) now explicitly wedded, glory given its Goddess. After all-marks (previous name) comes the Mark-bearer Herself: auspiciousness personified as Spouse. Fortune is thus relational, not accidental: wealth held where Lakṣmī is honoured. Wed one wealth wisely today: join a resource to a right purpose, prosperity to providence. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-362", title: "Samitiñjayaḥ", category: "Lotus-Resolve", summary: "Ever-victorious in assemblies. Samitiñjaya wins councils: contentions calmed, debates decided — victory by presence, not polemic, as the verse's commentary stresses. Terror, timing, marks, and fortune (previous names) converge in assembly: the fully-marked, Lakṣmī-wed Lord needs no argument. Presence persuades where proof provokes. Calm one contention today: enter a disagreement with presence rather than points. (Stotra verse 39.)", relatedVerseIds: ["vs-039"] },
  { id: "vs-nama-363", title: "Vikṣaraḥ", category: "Lotus-Resolve", summary: "Imperishable, undecaying flow. Vikṣara streams without spending: continuity unbroken, flowing unfailing — akṣara (name 17) now mobilized as current, the imperishable in motion. The new verse opens on permanence before path and cause: what guides (mārga) and grounds (hetu) must itself not pass. Streaming yet unspent: rivers as theology. Flow once today unfailingly: a constancy maintained in motion — duty done daily, love renewed. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-364", title: "Rohitaḥ", category: "Lotus-Resolve", summary: "Red-hued — the fish-form (Matsya) glowing red, dawn-coloured deliverer. Rohita consecrates colour: redness redeemed, hue hallowed — the Vedas' ruddy steed and dawn's redness gathered into one rosy name. After undecaying flow comes ruddy form: permanence wearing colour, eternity blushing. Colour is doctrine: redness signals ardour transmuted (as lohitākṣa, name 58, established). Hallow one hue today: notice a colour as His wearing. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-365", title: "Mārgaḥ", category: "Lotus-Resolve", summary: "The path to bliss (named again). Way re-walked: the road re-trod, direction re-pointed — guidance restated lest travellers forget the route amid red wonders and rope-bellies. Path after permanence (name 363): the road that does not pass, direction that does not shift. Every verse needs its path; this one re-lays it. Re-walk one road today: a proven practice — prayer, honesty, kindness — travelled again deliberately. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-366", title: "Hetuḥ", category: "Lotus-Resolve", summary: "Supreme cause of the universe. Hetu crowns causation: reasons rooted, explanations ending here — the why's terminus, the wherefore's well. Path (previous name) shows the way; cause explains why ways exist: direction needs derivation. The causation-cluster of verse 41 (karaṇa/kāraṇa/kartā) is previewed here in single syllable. Root one reason today: trace a blessing — or a burden — back past second causes to the First. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-367", title: "Dāmodaraḥ", category: "Lotus-Resolve", summary: "Rope-bellied — tied by Yaśodā's cord. Dāmodara ropes omnipotence with mother-love: the Boundless bound, infinity knotted by a mother's wrist-rope, and the mark remaining forever on the belly of God. Love's rope leaves its trace on omnipotence (verse theme): path, cause and patience frame this intimacy — direction, reason and endurance culminating in domestication. Knot once today lovingly: let a loved one's claim bind you without resentment. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-368", title: "Sahaḥ", category: "Lotus-Resolve", summary: "Patient endurance. Saha bears blessedly: tolerance transmuting, patience perfecting — forbearance as power held in reserve, strength declining to strike. The rope-bound Lord (previous name) wears patience as sequel: bound, yet unprotesting — omnipotence enduring a cord. Path, cause, patience travel together (verse theme): direction, reason, endurance. Bear once today blessedly: an irritation carried without transmitting it. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-369", title: "Mahīdharaḥ", category: "Lotus-Resolve", summary: "Supporter of earth (named again, as mahīdhara; with mahīdhara/dharaṇīdhara forms across tellings). Bearing restated: the ground re-grounded after rope, patience, path and cause — support repeated lest the verse's domestic intimacy obscure cosmic responsibility. The household God still holds the planet. Re-ground once today: feel the planet held while the household plays. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-370", title: "Mahābhāgaḥ", category: "Lotus-Resolve", summary: "Greatly fortunate, receiving worship's best share. Mahābhāga takes firstfruits by right: the preeminent portion — praise's cream, sacrifice's first cut — belonging where glory resides. Fortune here is not luck but dues: excellence receiving its acknowledgment. After earth-bearing (previous name) comes honour-rendering: support answered by share. First-fruit one offering today: the day's best hour, or best effort, given first — not from remainder. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-371", title: "Vegavān", category: "Lotus-Resolve", summary: "Swift to reach devotees. Vegavān hurries helpfully: haste heaven-hearted, speed in service — swiftly, yet never hurried (verse theme): velocity without agitation, arrival without alarm. The fortunate Lord (previous name) is also the fast Lord: glory with wings, Garuḍa-banner (name 354) now explained as haste. Delay is not distance; He is swift, though we are slow. Hurry once today helpfully: an errand of mercy, done fast and calmly. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-372", title: "Amitāśanaḥ", category: "Lotus-Resolve", summary: "Of endless appetite. Amitāśana hungers holily: consumption cosmic, eating unending — oblations, offerings, ages, worlds all fuel for fire unfilled. Mahāśana (name 303) returns amplified: devouring then stated, now unstinted — appetite declared endless, not merely great. Hunger is His fullness inverted: capacity infinite expressing as craving. Feed one endless hunger rightly today: offer effort, praise, or self into fire that never fills yet always warms. (Stotra verse 40.)", relatedVerseIds: ["vs-040"] },
  { id: "vs-nama-373", title: "Udbhavaḥ", category: "Lotus-Resolve", summary: "Originator of the universe (named again, as udbhava: origination re-originated). Beginning re-begun: the origin restated after appetite — He who eats all (previous name) also starts all, devourer and dawn one Person. Causation's anatomy (verse theme) opens here: origin first, then churning, shining, womb, lordship, instrument, cause, maker, unmaker, depth, cave. Re-begin once today: a stalled thing, originated afresh under His origin. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-374", title: "Kṣobhaṇaḥ", category: "Lotus-Resolve", summary: "Thriller of the world with life. Kṣobhaṇa stirs stillness: calm quickened, the placid agitated into aliveness — churning precedes shining (verse theme): agitation is creation's method, disturbance its mercy (as janārdana, name 126, established). Stagnation is the only true death; stirring, even painful, is birth. The originator (previous name) originates by agitating: creation as holy commotion. Quicken one calm today: stir a stagnant thing with life. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-375", title: "Devaḥ", category: "Lotus-Resolve", summary: "Shining — revelled, praised, luminous. Deva is luminosity lauded: brightness hymned, glory sung — the shining that follows churning (verse theme), agitation ripening into radiance. Play (dīv) is His root: shining, sporting, praising all one family — light that plays, play that illuminates. After origin and stirring comes gleam: creation's method flowering into creation's beauty. Gleam once today hymnally: shine — and let the shining praise its Source. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-376", title: "Śrīgarbhaḥ", category: "Lotus-Resolve", summary: "Womb of Śrī, containing all glories. Śrīgarbha gestates splendour: glories grown within, grandeur gravid — Lakṣmī's lord (name 361) now Her bearer, fortune's husband become fortune's womb. Shining (previous name) deepens into containing: radiance held, not merely radiated. Glory grown inwardly before displayed outwardly. Grow one glory inwardly today: a good — skill, virtue, plan — gestated quietly before announcement. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-377", title: "Parameśvaraḥ", category: "Lotus-Resolve", summary: "Supreme Lord. Parameśvara climaxes command: authority's apex, lordship ultimate — every lesser lordship (parent, teacher, king) borrowing legitimacy here, as zones 1–3 established of īśvara-names. The causation-verse stations supremacy mid-toolkit: instrument, cause, maker surround the Master who wields them. Supremacy that makes, not merely rules: Lord as Maker-in-chief. Bow once today ultimately: a deference reserved for the Apex alone. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-378", title: "Karaṇam", category: "Lotus-Resolve", summary: "Instrument of creation. Karaṇa sanctifies means: tools transfigured, implements inspired — the Supreme Lord (previous name) wielding, and being, the wherewithal. Instrument after supremacy humbles philosophy: the Highest consents to means, method, mediation — grace using handles. Hands, words, hours are karaṇas when lent to Him. Use one tool sacredly today: an ordinary implement, wielded as His instrument. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-379", title: "Kāraṇam", category: "Lotus-Resolve", summary: "Cause of creation. Kāraṇa roots reason: the why's terminus, the wherefore's well — hetu (name 366) now seated inside the full toolkit, single cause among instrument, maker, unmaker. Cause after instrument orders the workshop: means serve reason, tools answer purpose. Drink once today deeply: from the well — ask one why past second causes, and rest at the First. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-380", title: "Kartā", category: "Lotus-Resolve", summary: "The doer. Kartṛ authors absolutely: all doing His doing, every act authored — agency's fountainhead, the hand behind hands. Instrument and cause (previous names) converge here: means and reason meeting in the Maker. Human agency participates, never competes: our doing is His doing delegated. Author one act consciously today: done as His, signed with attention, offered back. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-381", title: "Vikartā", category: "Lotus-Resolve", summary: "Maker of varieties, and unmaker of forms. Vikartṛ delights in diversity: differences designed, variations valued — the Doer (previous name) diversifying, unity revelling in multiplicity. Unmaking belongs here too: variety requires revision, forms yield to new forms. Diversity is not division but delight: many, yet His. Value one variation today: a difference — of person, taste, fortune — honoured as His design. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-382", title: "Gahanaḥ", category: "Lotus-Resolve", summary: "Deep, hard to know in form and act. Gahana protects profundity: depths defending deity from glibness — tools (karaṇa), causes, makings all dissolving into mystery where the toolkit ends and the cave begins (next name). The causation-arc deliberately drowns in depth: explanation complete, then explanation exceeded. Depth is not obscurity but superabundance of meaning. Plumb one profundity today: stay with an unanswerable past the urge to solve it. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-383", title: "Guhaḥ", category: "Lotus-Resolve", summary: "Dweller in the heart's cave. Guha inhabits interiority: the innermost inhabited, secrecy shared — the deep (previous name) given address, mystery housed in the heart-cave (guhā). Toolkit dissolving into cave-mystery (verse theme): instrument, cause, maker, variety all ending where He dwells nearest — inside. Enter the cave (verse counsel): sit with one unanswerable, and find it inhabited. Share one secrecy today: your heart-cave's door, opened to Him. (Stotra verse 41.)", relatedVerseIds: ["vs-041"] },
  { id: "vs-nama-384", title: "Vyavasāyaḥ", category: "Lotus-Resolve", summary: "The resolute — resolve itself. Vyavasāya steels purpose: intention ironed, decision tempered — the Gītā's vyavasāyātmikā buddhi (resolute intellect, II.41) worn as God's own name. Resolve opens the dwelling-verse: decisions becoming dwellings (verse theme) — purpose hardening into foundation, abode, place, firmness. His resolve never wavers; ours borrows steadiness from His. Temper one purpose today: a decision, heated and cooled into steel. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-385", title: "Vyavasthānaḥ", category: "Lotus-Resolve", summary: "Ordered foundation, substratum of arrangement. Vyavasthāna undergirds order: arrangement beneath appearances, the settled where unsteady things lodge — resolve (previous name) hardened into footing. Adhiṣṭhāna (name 324) returns as establishment's scaffolding: substratum now structured, ground given grammar. Order is mercy's architecture. Arrange one beneath today: put order under something wobbling — a room, a schedule, a mind. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-386", title: "Saṃsthānaḥ", category: "Lotus-Resolve", summary: "Ultimate abode and authority. Saṃsthāna stations supremely: standing's summit, statehood's source — foundation (previous name) raised into capital, footing crowned. Dhāman the abode (name 211) returns as consummation: arrival's address now ultimate, home at the top of dwellings. Resolve became foundation, foundation became capital. Stand once today supremely: take your stand at the highest — principle, not convenience. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-387", title: "Sthānadaḥ", category: "Lotus-Resolve", summary: "Giver of right abode to all. Sthānada places providently: stations assigned, seats settled — the ultimate Abode (previous name) distributing abodes, home sharing homelessness' cure. Dhruva's devotees get planets; the humble get corners; all get somewhere. Placement is providence particularized. Settle one seat kindly today: give someone — or yourself — a right place: role, rest, welcome. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-388", title: "Dhruvaḥ", category: "Lotus-Resolve", summary: "The firm and imperishable (named again, as dhruva: fixity re-fixed). Permanence re-pinned: sthira (name 203) and sthavirodhruva (name 54) returning as pure pole-star — the landmark outlasting maps, fixity's very name. Abodes given (previous name) need an unmoving Giver: placements hold because Placer holds. Re-pin one permanence today: a principle re-driven like a survey-stake. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-389", title: "Pararddhiḥ", category: "Lotus-Resolve", summary: "Lord of supreme manifestations. Pararddhi exhibits eminence: heights shown, summits displayed — prosperity (ṛddhi) raised to supreme, abundance exhibited rather than hoarded. Firmness (previous name) flowers into display: permanence confident enough to show itself. Heights shown to draw climbers, not to dazzle them. Display one height humbly today: an excellence, shown to invite — not to impress. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-390", title: "Paramaspaṣṭaḥ", category: "Lotus-Resolve", summary: "Supremely clear, extremely vivid. Paramaspaṣṭa perfects plainness: obviousness owned, clarity climactic — spaṣṭākṣara (name 279) grown from syllables to sunshine, mystery spelled plainly now blazing plainly. Manifestation (previous name) ripening into legibility: heights shown (pararddhi) become heights readable. Clarity ripens into nourishment (verse theme): clear seeing feeds. Clarify one obscurity today: plain words on a muddled matter. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-391", title: "Tuṣṭaḥ", category: "Lotus-Resolve", summary: "Ever-contented. Tuṣṭa rests satisfied: want's absence, peace's presence — contentment as nature, not achievement. Clarity (previous name) ripens into contentment (verse theme): clear seeing feeds, feeding satisfies. The Giver of abodes (name 387) is Himself at home: housed-ness perfected. Satisfaction settled is strength stored. Rest once today contented: a complete pause — fed, housed, held — asking nothing. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-392", title: "Puṣṭaḥ", category: "Lotus-Resolve", summary: "Ever-full and nourished. Puṣṭa maintains plenty: fullness fed, abundance perpetuated — contentment (previous name) fleshed out, satisfaction given body. Nourishment (verse theme) follows clarity through contentment: seeing, resting, fed. The nourisher (vardhana, śarīrabhṛt) is Himself nourished — fullness keeping fullness. Maintain one plenty today: feed a fullness — health, friendship, practice — so it perpetuates. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-393", title: "Śubhekṣaṇaḥ", category: "Lotus-Resolve", summary: "Whose gaze brings auspiciousness. Śubhekṣaṇa graces by glancing: looks luckening, sights sweetening — the lotus-eyes' career crowned, vision now frankly fortuning. His gaze (verse theme) feeds auspiciously: clarity, contentment, nourishment all delivered through looking. To be seen is to be blessed; regard is providence. Sweeten one sight today: look at someone — or something — until it brightens under looking. (Stotra verse 42.)", relatedVerseIds: ["vs-042"] },
  { id: "vs-nama-394", title: "Rāmaḥ", category: "Lotus-Resolve", summary: "Rāma — the delightful, prince of Ayodhyā. Rāma delights and steadies: joy's name that steadies (verse theme: delight that steadies and cleanses) — beauty with backbone, gladness with governance. Rest (virāma) and dustlessness (viraja) follow: the Prince who steadies and cleanses, delight's aftermath made doctrine. Walk one stretch of path without raising dust (verse counsel): gladness that settles rather than stirs. Delight once today steadily: a joy that steadies its beholders. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-395", title: "Virāmaḥ", category: "Lotus-Resolve", summary: "Rest, the end of all activities. Virāma moors motion: labour laid down, movement harboured — delight (previous name) settling into stillness, gladness coming home. Rest is not mere absence but arrival: activities ending the way rivers end — in ocean. The prince who delights also rests creation: every labour moored nightly, every age moored finally. Moor once today restfully: lay a labour down completely, even briefly. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-396", title: "Virajaḥ", category: "Lotus-Resolve", summary: "Dustless, passionless. Virajas clears cloudlessly: no speck, no stain, no stir — delight (name 394) cleansed of residue, rest (previous name) without dust. Rajas is dust and passion both: the storm of particles and the storm of desires settled together. The prince who steadies and cleanses (verse theme) is stainless in both senses. Clear one speck today: a small stain — of temper, of motive — wiped before it spreads. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-397", title: "Mārgaḥ", category: "Lotus-Resolve", summary: "The path to immortality (named again). Way re-walked toward deathlessness: direction death-defying — mārga (name 365) now aimed explicitly past dying, the road given its destination. Path, led, leader, unleaded (verse theme: guidance entire) begin here: the way itself, before its walkers and guides. Walk death-defyingly once today: a step — of courage, of truth — taken as though dying were not the argument. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-398", title: "Neyaḥ", category: "Lotus-Resolve", summary: "To be led — the guidable, and the Guide who lets Himself be led by love. Neya holds both: living beings to be guided, and the Lord guidable by devotion — Yaśodā's rope (name 367) previewed in grammar. Guidance entire (verse theme) needs the led: paths and leaders exist for walkers. Lendability crowns leadership: strength that accepts direction. Deal one direction today: guide someone guidable — gently, particularly. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-399", title: "Nayaḥ", category: "Lotus-Resolve", summary: "Who leads by policy and wisdom. Naya conducts cleverly: strategy sacred, prudence praised — netā (name 222) now politic, leadership given statecraft. Conduct clever is conduct kind when He conducts: policy in service of persons, wisdom spending itself on welfare. Guidance entire (verse theme) gains its method: path, led, and now leading-well. Lead once today wisely: a decision — small or great — taken with strategy in service of kindness. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
  { id: "vs-nama-400", title: "Anayaḥ", category: "Lotus-Resolve", summary: "Led by none, the unleaded. Anaya depends on nothing: guidance needing none, direction dealing all — the Guide un-guided, the Leader un-led. Guidance entire (verse theme) completes in paradox: path, led, leader — and the unleaded who grounds them all, independence guaranteeing every dependence. Even the unguided are His charge (verse commentary): the unleaded leads precisely those whom none leads. Depend once today on the Independent: lean on the Unleaning. (Stotra verse 43.)", relatedVerseIds: ["vs-043"] },
];